// Section 12: evidence-based findings — facts about the data on this page, each
// with its period and the series it came from. Generated by deterministic
// templates (src/lib/inflation/findings.ts), not by a model, and never causal.
// Server component.

import { LeadMore } from "@/components/shell/Disclosure";
import { buildFindings } from "@/lib/inflation/findings";
import type { InflationViewModel } from "@/lib/inflation/viewModel";

export default function FindingsSection({ model }: { model: InflationViewModel }) {
  const findings = buildFindings(model);
  if (findings.length === 0) {
    return <p className="text-[13px] text-pe-text-2">There is not enough data to state findings right now.</p>;
  }
  return (
    <div>
      <p className="mb-3 max-w-3xl text-[13px] leading-relaxed text-pe-text-2">
        Plain statements of what the data above shows. Each names its period and source. They describe <strong className="font-medium text-pe-text">what</strong> the numbers are, not <strong className="font-medium text-pe-text">why</strong>: the data on this page cannot establish causes.
      </p>
      <ol className="flex flex-col divide-y divide-pe-border rounded-[var(--pe-radius)] border border-pe-border">
        {findings.map((f) => (
          <li key={f.id} className="px-4 py-3">
            <LeadMore leadClassName="text-[14px] leading-relaxed text-pe-text">{f.text}</LeadMore>
            <p className="mt-1 font-mono text-[11px] text-pe-text-3">
              Period: {f.period} · Basis: {f.basis}
            </p>
          </li>
        ))}
      </ol>
    </div>
  );
}
